parameters.jsCode:
// This code:
// 1. Reads the AI-generated response from content.parts[0].text.
// 2. Processes multiple AI response items dynamically.
// 3. Extracts the complete "WHO YOU'RE TALKING TO" section.
// 4. Extracts the complete "DEAL STATUS" section.
// 5. Extracts the contact name and company.
// 6. Extracts the deal stage, deal value, and last contact date.
// 7. Extracts the complete "KEY CONTEXT" section.
// 8. Extracts the complete "SUGGESTED TALKING POINTS" section.
// 9. Extracts the scheduled call time.
// 10. Calculates the notification time as exactly 30 minutes before the call.
// 11. Calculates how many minutes remain until the notification time.
// 12. If today's call time has passed, treats the call as tomorrow's call.
// 13. Ignores thoughtSignature and other unnecessary fields.
// 14. Returns clean, individually mappable JSON fields.

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  // Get the AI-generated text
  const text = data?.content?.parts?.[0]?.text || "";

  // Extract sections
  const whoYoureTalkingTo =
    text.match(
      /WHO YOU'?RE TALKING TO\s*([\s\S]*?)(?=\n\s*DEAL STATUS)/i
    )?.[1]?.trim() || "";

  const dealStatus =
    text.match(
      /DEAL STATUS\s*([\s\S]*?)(?=\n\s*KEY CONTEXT)/i
    )?.[1]?.trim() || "";

  const keyContext =
    text.match(
      /KEY CONTEXT\s*([\s\S]*?)(?=\n\s*SUGGESTED TALKING POINTS)/i
    )?.[1]?.trim() || "";

  const suggestedTalkingPoints =
    text.match(
      /SUGGESTED TALKING POINTS\s*([\s\S]*?)(?=\n\s*CALL SCHEDULE)/i
    )?.[1]?.trim() || "";

  const scheduledTime =
    text.match(
      /CALL SCHEDULE[\s\S]*?(\d{1,2}):(\d{2})/i
    );

  const scheduledHour = scheduledTime
    ? parseInt(scheduledTime[1], 10)
    : null;

  const scheduledMinute = scheduledTime
    ? parseInt(scheduledTime[2], 10)
    : null;

  // Extract contact name and company
  const contactMatch = whoYoureTalkingTo.match(
    /(?:speaking with\s+)?([A-Za-zÀ-ÿ'-]+(?:\s+[A-Za-zÀ-ÿ'-]+)*)\s+from\s+(.+?)(?:\s+is\s+|\.\s*$|\s*$)/i
  );

  let contactName = "";
  let company = "";

  if (contactMatch) {
    contactName = contactMatch[1].trim();
    company = contactMatch[2].trim();
  }

  // Extract deal stage
  let dealStage =
    dealStatus.match(
      /deal\s+stage\s+is\s+(.+?)(?:\.|,|$)/i
    )?.[1]?.trim() || "";

  if (!dealStage) {
    dealStage =
      dealStatus.match(
        /deal\s+is\s+in\s+the\s+(.+?)\s+stage/i
      )?.[1]?.trim() || "";
  }

  // Extract deal value
  const dealValueMatch = dealStatus.match(
    /(?:deal\s+value\s+is|valued\s+at)\s+([\d,]+(?:\.\d+)?)\s*USD/i
  );

  const dealValue = dealValueMatch
    ? parseFloat(dealValueMatch[1].replace(/,/g, ""))
    : null;

  // Extract currency
  const currency = /USD/i.test(dealStatus) ? "USD" : "";

  // Extract last contact
  const lastContact =
    dealStatus.match(
      /last\s+contact\s+was\s+(?:on\s+)?(.+?)(?:\.|$)/i
    )?.[1]?.trim() || "";

  // Calculate scheduled call and notification time
  let scheduledDateTime = null;
  let notificationDateTime = null;
  let notificationTime = "";
  let minutesRemaining = null;

  if (
    scheduledHour !== null &&
    scheduledMinute !== null
  ) {
    const now = new Date();

    // Start with today's date
    scheduledDateTime = new Date(now);

    scheduledDateTime.setHours(
      scheduledHour,
      scheduledMinute,
      0,
      0
    );

    // If today's call time has already passed,
    // schedule it for tomorrow.
    if (scheduledDateTime <= now) {
      scheduledDateTime.setDate(
        scheduledDateTime.getDate() + 1
      );
    }

    // Notification is exactly 30 minutes before the call
    notificationDateTime = new Date(scheduledDateTime);

    notificationDateTime.setMinutes(
      notificationDateTime.getMinutes() - 30
    );

    notificationTime = notificationDateTime.toLocaleTimeString(
      "en-GB",
      {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }
    );

    // Minutes remaining until notification time
    minutesRemaining = Math.ceil(
      (notificationDateTime.getTime() - now.getTime()) /
        (1000 * 60)
    );
  }

  return {
    json: {
      // Complete original sections
      whoYoureTalkingTo,
      dealStatus,
      keyContext,
      suggestedTalkingPoints,

      // Extracted contact information
      contactName,
      company,

      // Extracted deal information
      dealStage,
      dealValue,
      currency,
      lastContact,

      // Call schedule
      scheduledTime:
        scheduledTime
          ? `${String(scheduledHour).padStart(2, "0")}:${String(
              scheduledMinute
            ).padStart(2, "0")}`
          : "",

      notificationTime,
      scheduledDateTime:
        scheduledDateTime
          ? scheduledDateTime.toISOString()
          : null,

      notificationDateTime:
        notificationDateTime
          ? notificationDateTime.toISOString()
          : null,

      minutesRemaining
    }
  };
});

